import React, { useMemo } from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { Circle } from "@remotion/shapes";

{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}

// Schema Definition




export type InfographicRingsProps = Record<string, any>;

// Sub-component for individual Rings
const ProgressRing: React.FC<{
  percentage: number;
  label: string;
  color: string;
  thickness: number;
  delay: number;
  index: number;
  radius: number;
}> = ({ percentage, label, color, thickness, delay, index, radius }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Entrance Spring
  const scale = spring({
    frame: frame - delay,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  // Progress Animation
  const progressDuration = 45; // frames
  const progressStart = delay + 15;
  const currentProgress = interpolate(
    frame,
    [progressStart, progressStart + progressDuration],
    [0, percentage / 100],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Counter Text
  const counterValue = Math.round(
    interpolate(
      frame,
      [progressStart, progressStart + progressDuration],
      [0, percentage],
      {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      }
    )
  );

  // Label Fade In
  const labelOpacity = interpolate(
    frame,
    [progressStart + 10, progressStart + 30],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const circumference = 2 * Math.PI * radius;
  const strokeDashoffset = circumference * (1 - currentProgress);

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "flex-start",
        transform: `scale(${scale})`,
        opacity: Math.min(1, Math.max(0, (frame - delay) / 10)), // Simple fade in for initial visibility
        width: radius * 2 + thickness,
      }}
    >
      {/* Ring Container */}
      <div
        style={{
          position: "relative",
          width: radius * 2,
          height: radius * 2,
          marginBottom: 20,
        }}
      >
        {/* Background Ring (Dimmed) */}
        <div style={{ position: "absolute", opacity: 0.2 }}>
          <Circle
            radius={radius}
            stroke={color}
            strokeWidth={thickness}
            fill="transparent"
          />
        </div>

        {/* Foreground Ring (Animated) */}
        <div style={{ position: "absolute", transform: "rotate(-90deg)" }}>
          <Circle
            radius={radius}
            stroke={color}
            strokeWidth={thickness}
            fill="transparent"
            strokeDasharray={circumference}
            strokeDashoffset={strokeDashoffset}
            strokeLinecap="round"
          />
        </div>

        {/* Percentage Text */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontFamily: "Montserrat",
            fontWeight: 800,
            fontSize: radius * 0.6,
            color: "#ffffff",
          }}
        >
          {counterValue}%
        </div>
      </div>

      {/* Label Text */}
      <div
        style={{
          fontFamily: "Montserrat",
          fontWeight: 700,
          fontSize: 24,
          color: "#ffffff",
          textTransform: "uppercase",
          letterSpacing: "1px",
          opacity: labelOpacity,
          transform: `translateY(${(1 - labelOpacity) * 10}px)`,
        }}
      >
        {label}
      </div>
    </div>
  );
};

const InfographicRings: React.FC<InfographicRingsProps> = ({
  backgroundColor = "#500000",
  gradientEndColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 10,
  mainTitle = "YOUR TEXT",
  ringThickness = 15,
  ringRadius = 100,
  items = [
    { percentage: 25, label: "Text Line 1", color: "#d90429" },
    { percentage: 50, label: "Text Line 2", color: "#3a86ff" },
    { percentage: 75, label: "Text Line 3", color: "#ffbe0b" },
    { percentage: 100, label: "Text Line 4", color: "#38b000" },
  ],
}) => {
  useFontLoader(["Montserrat"]);

  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  // Background Logic
  const bgStyle: React.CSSProperties = transparentBackground
    ? {}
    : {
        background: `linear-gradient(135deg, ${backgroundColor} 0%, ${gradientEndColor} 100%)`,
      };

  // Title Animation
  const titleOpacity = interpolate(frame, [0, 20], [0, 1], {
    extrapolateRight: "clamp",
  });
  const titleY = interpolate(frame, [0, 30], [-50, 0], {
    extrapolateRight: "clamp",
    easing: (t) => 1 - Math.pow(1 - t, 3), // cubic ease out
  });

  // Calculate layout
  const gap = 60; // Gap between items

  return (
    <AbsoluteFill style={{ ...bgStyle }}>
      {/* Main Container */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          width: "100%",
          height: "100%",
          paddingTop: 40,
        }}
      >
        {/* Main Title */}
        <h1
          style={{
            fontFamily: "Montserrat",
            fontSize: 80,
            fontWeight: 700,
            color: "white",
            marginBottom: 80,
            opacity: titleOpacity,
            transform: `translateY(${titleY}px)`,
            textTransform: "uppercase",
            letterSpacing: "2px",
          }}
        >
          {mainTitle}
        </h1>

        {/* Rings Container */}
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            justifyContent: "center",
            alignItems: "flex-start",
            gap: gap,
            width: "100%",
            padding: "0 40px",
            flexWrap: "wrap",
          }}
        >
          {items.map((item, index) => (
            <ProgressRing
              key={index}
              index={index}
              percentage={item.percentage}
              label={item.label}
              color={item.color}
              thickness={ringThickness}
              delay={15 + index * 10} // Staggered start
              radius={ringRadius}
            />
          ))}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default InfographicRings;